package net.dogpoo.api.core.weaver.service;
import java.util.*;import java.time.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.web.server.ResponseStatusException;import org.springframework.test.util.ReflectionTestUtils;
import net.dogpoo.api.core.weaver.mapper.*;import net.dogpoo.api.core.weaver.model.*;
class WeaverWorkspacePolicyTest {
 WeaverPolicyMapper db=mock(WeaverPolicyMapper.class);WeaverWorkspaceMapper spaces=mock(WeaverWorkspaceMapper.class);WeaverSharingMapper members=mock(WeaverSharingMapper.class);
 WeaverWorkspacePolicyService policy=new WeaverWorkspacePolicyService(db,spaces,members);
 @BeforeEach void setup(){when(spaces.owner("w")).thenReturn("owner");when(spaces.revision("w")).thenReturn(1L);when(db.plan("w")).thenReturn(Map.of("code","free","editor_limit",2));when(db.plans()).thenReturn(List.of(Map.of("code","free")));}
 @Test void joinedMembershipsNeverConsumeOwnedQuota(){when(db.plans()).thenReturn(List.of(Map.of("code","free","owned_limit",1)));policy.admission("guest");verifyNoInteractions(members);}
 @Test void ownedLimitBlocksAdmissionAtBoundary(){when(db.plans()).thenReturn(List.of(Map.of("code","free","owned_limit",1)));when(db.owned("owner")).thenReturn(List.of(Map.of("workspaceId","w","plan","free")));assertEquals(422,assertThrows(ResponseStatusException.class,()->policy.admission("owner")).getStatusCode().value());}
 @Test void unspecifiedLimitsRemainUnlimited(){assertNull(policy.ownedLimit("owner"));policy.admission("owner");}
 @Test void freeHasOwnerAndOneEditor(){when(db.editors("w")).thenReturn(List.of("a","b"));assertTrue(policy.editorAllowed("w","a"));assertFalse(policy.editorAllowed("w","b"));when(members.editors("w")).thenReturn(1);assertThrows(ResponseStatusException.class,()->policy.editorSeat("w",1));}
 @Test void paidSpaceAllowsFreeAccountEditorWithUnlimitedPaidSeats(){when(db.plan("w")).thenReturn(Map.of("code","pro"));assertTrue(policy.editorAllowed("w","free-user"));policy.editorSeat("w",1);}
 @Test void restorationRequiresPaidEntitlement(){assertThrows(ResponseStatusException.class,()->policy.validateRestore("owner","w"));when(db.plan("w")).thenReturn(Map.of("code","pro"));policy.validateRestore("owner","w");}
 @Test void restoreRejectsStorageAndDocumentOverflow(){when(db.plan("w")).thenReturn(Map.of("code","pro","storage_limit",100L,"document_limit",2));when(db.bytes("w")).thenReturn(101L);assertThrows(ResponseStatusException.class,()->policy.validateRestore("owner","w"));when(db.bytes("w")).thenReturn(100L);when(db.documents("w")).thenReturn(3L);assertThrows(ResponseStatusException.class,()->policy.validateRestore("owner","w"));}
 @Test void documentOverflowAllowsSameCountEditsButNotNewDocuments(){when(db.plan("w")).thenReturn(Map.of("code","free","document_limit",1));when(db.documents("w")).thenReturn(3L);policy.validateSave("w",List.of(),0,3);assertThrows(ResponseStatusException.class,()->policy.validateSave("w",List.of(),0,2));}
 @Test void storageOverflowAllowsShrinkAndRejectsGrowth(){when(db.plan("w")).thenReturn(Map.of("code","free","storage_limit",100L));when(db.bytes("w")).thenReturn(120L);policy.validateSave("w",List.of(),130,0);assertThrows(ResponseStatusException.class,()->policy.validateSave("w",List.of(),110,0));assertThrows(ResponseStatusException.class,()->policy.validateMedia("w",1));}
 @Test void ordinaryUserCannotUseAdminQueriesOrMutations(){assertThrows(ResponseStatusException.class,()->policy.adminUsers("guest",""));assertThrows(ResponseStatusException.class,()->policy.adminRole("guest","owner","admin"));assertThrows(ResponseStatusException.class,()->policy.adminSubscription("guest","w","pro",Instant.now().plusSeconds(1000).toString(),false));verify(db,never()).subscribe(anyString(),anyString(),any(),anyBoolean());}
 @Test void lastAdministratorCannotBeDemoted(){when(db.platformRole("owner")).thenReturn("admin");when(db.admins()).thenReturn(1);assertThrows(ResponseStatusException.class,()->policy.adminRole("owner","owner","user"));verify(db,never()).platformRoleSet(anyString(),anyString());}
 @Test void administratorRoleChangesAreAudited(){when(db.platformRole("owner")).thenReturn("admin");when(db.platformRole("target")).thenReturn("user");policy.adminRole("owner","target","admin");verify(db).platformRoleSet("target","admin");verify(db).audit("owner","account_role","target","user -> admin");}
 @Test void cancellationIsOwnerOnlyAndDoesNotChangeEndDate(){when(db.cancel("w",true)).thenReturn(1);policy.cancel("owner","w",true);verify(db).cancel("w",true);verify(db,never()).subscribe(anyString(),anyString(),any(),anyBoolean());assertThrows(ResponseStatusException.class,()->policy.cancel("guest","w",true));}
 @Test void invalidAdminSubscriptionCannotGrantAccess(){when(db.platformRole("owner")).thenReturn("admin");assertThrows(ResponseStatusException.class,()->policy.adminSubscription("owner","w","pro","yesterday",false));assertThrows(ResponseStatusException.class,()->policy.adminSubscription("owner","w","pro",Instant.now().minusSeconds(1).toString(),false));}
 @Test void newAccountsAreProvisionedExactlyOnce(){when(db.provisioned("new")).thenReturn(0,1);policy.initializeAccount("new");policy.initializeAccount("new");verify(spaces,times(1)).ensure("new");verify(db,times(1)).provision("new");}
 @Test void emptyCatalogDoesNotCreateAWorkspace(){var accounts=mock(WeaverSessionMapper.class);var sharing=new WeaverSharingService(spaces,members,accounts);ReflectionTestUtils.setField(sharing,"policy",policy);assertNull(sharing.catalog("owner","owner@test.invalid").get("defaultWorkspaceId"));verify(spaces,never()).ensure(anyString());verify(spaces,never()).create(anyString(),anyString());}
 @Test void usedFreeSpaceDeletesPermanentlyAfterVerification(){var lifecycle=mock(WeaverWorkspaceLifecycleMapper.class);var accounts=mock(WeaverSessionMapper.class);var deletion=mock(WeaverWithdrawalMapper.class);var service=new WeaverWorkspaceLifecycleService(spaces,lifecycle,accounts,deletion,mock(WeaverVerificationMail.class));ReflectionTestUtils.setField(service,"policy",policy);when(accounts.account("owner")).thenReturn(new WeaverAccount("owner","owner@test.invalid",null,null));when(lifecycle.used("w")).thenReturn(true);when(lifecycle.valid(eq("w"),eq("owner"),anyString())).thenReturn(1);assertEquals(0,service.preview("owner","w").get("retentionDays"));assertEquals(false,service.delete("owner","w","12345678").get("archived"));verify(spaces).deleteWorkspace("w");verify(lifecycle,never()).archive("w");}
 @Test void paidDeletionRetainsThirtyDays(){var lifecycle=mock(WeaverWorkspaceLifecycleMapper.class);var accounts=mock(WeaverSessionMapper.class);var deletion=mock(WeaverWithdrawalMapper.class);var service=new WeaverWorkspaceLifecycleService(spaces,lifecycle,accounts,deletion,mock(WeaverVerificationMail.class));ReflectionTestUtils.setField(service,"policy",policy);when(accounts.account("owner")).thenReturn(new WeaverAccount("owner","owner@test.invalid",null,null));when(db.plan("w")).thenReturn(Map.of("code","pro"));when(lifecycle.used("w")).thenReturn(true);when(lifecycle.valid(eq("w"),eq("owner"),anyString())).thenReturn(1);assertEquals(30,service.delete("owner","w","12345678").get("retentionDays"));verify(lifecycle).archive("w");verifyNoInteractions(deletion);}
 @Test void editorSelectionRejectsOutsidersAndKeepsOwnerSeat(){when(members.members("w")).thenReturn(List.of(Map.of("userId","a"),Map.of("userId","b")));assertThrows(ResponseStatusException.class,()->policy.chooseEditors("owner","w",List.of("a","b")));assertThrows(ResponseStatusException.class,()->policy.chooseEditors("owner","w",List.of("outsider")));policy.chooseEditors("owner","w",List.of("b"));verify(members).setRole("w","a","viewer");verify(members).setRole("w","b","editor");}
}
